class Solution:
    def uniqueOccurrences(self, arr: List[int]) -> bool:
        # 每种数字都重新数一遍它出现了几次
        freqs = []
        for i in range(len(arr)):
            if arr[i] in arr[:i]:      # 同一个数只数第一次
                continue
            c = 0
            for j in range(len(arr)):
                if arr[j] == arr[i]:
                    c += 1
            freqs.append(c)
        # 再两两比较，看有没有两个数出现次数相同
        for i in range(len(freqs)):
            for j in range(i + 1, len(freqs)):
                if freqs[i] == freqs[j]:
                    return False
        return True

