def build_tree(inorder, postorder):
    pos = {}
    for i, v in enumerate(inorder):
        pos[v] = i

    def go(l, r, pr):
        if l > r:
            return None
        root = TreeNode(postorder[pr])
        k = pos[root.val]
        root.left = go(l, k - 1, pr - (r - k) - 1)
        root.right = go(k + 1, r, pr - 1)
        return root

