def serialize(root):
    if not root:
        return "[]"
    parts = []
    q = [root]
    while q:
        node = q.pop(0)
        if node is None:
            parts.append("null")
            continue
        parts.append(str(node.val))
        q.append(node.left)
        q.append(node.right)
    while parts and parts[-1] == "null":
        parts.pop()
    return "[" + ",".join(parts) + "]"


